import pandas as pd, re, unicodedata
from collections import defaultdict

logs=pd.read_csv('/app/data/test_center_logs.csv')
codebooks={}
for p in ['P1_POWER','P2_CTRL','P3_RF']:
    codebooks[p]=pd.read_csv(f'/app/data/codebook_{p}.csv')

canonical_set={'open','short','cold','missing','fixture','program','esd','pressure','contamination','connector','hipot','current','boot','calibration','version','rf_cal','firmware','reset','brownout'}
# synonyms/phrase map
phrase_map={
    '开路':'open','断路':'open','open circuit':'open','open':'open','os':'open',
    '短路':'short','short circuit':'short','short':'short','桥连':'short','连锡':'short','锡桥':'short','solder bridge':'short','bridge':'short',
    '虚焊':'cold','冷焊':'cold','cold solder':'cold','浮高':'cold','少锡':'cold','缺焊':'cold','intermittent':'cold','功能不稳':'cold','不稳定':'cold','偶尔':'cold',
    '少件':'missing','缺件':'missing','missing':'missing','漏件':'missing','缺料':'missing',
    '接触不良':'fixture','治具':'fixture','探针':'fixture','pogo':'fixture','fixture':'fixture','probe':'fixture','clamp':'fixture','reseat':'fixture','contact unstable':'fixture',
    '烧录失败':'program','写入失败':'program','flash fail':'program','write fail':'program','program fail':'program','programming failed':'program','reflash':'program','烧录':'program','flash':'program',
    'esd':'esd','静电':'esd',
    'pressure mark':'pressure','压伤':'pressure','pad damage':'pressure',
    '污染':'contamination','残留':'contamination','助焊剂':'contamination','contamination':'contamination','residue':'contamination','清洗':'contamination',
    'connector':'connector','sma':'connector','插拔':'connector','insertion loss':'connector',
    'hipot':'hipot','hi-pot':'hipot','leakage':'hipot','漏电':'hipot','绝缘不良':'hipot','绝缘':'hipot',
    'current high':'current','功耗高':'current','静态电流':'current','icc':'current','idle current':'current','abnormal consumption':'current',
    'boot fail':'boot','os fail':'boot','启动失败':'boot','stuck':'boot','卡死':'boot',
    'calibration':'calibration','rf cal':'calibration','rf_cal':'calibration',
    'version':'version','fw':'version','firmware':'version',
    'brownout_reset':'reset','brownout reset':'reset','reset':'reset'
}
phrase_items=sorted(phrase_map.items(), key=lambda x: -len(x[0]))

word_re=re.compile(r'[A-Za-z0-9_]+|[\u4e00-\u9fff]+')

stop_tokens={'fail','suspect','possible','issue','problem','ok','ng','seen','abnormal','unstable','intermittent','suspected','maybe','like','over','spec','data','r','w','rw','r/w','recal','retest','confirm','station','failcode','code','note','suggest','verify','check','ng','pass','ok', 'ok了'}


def normalize_text(text):
    return unicodedata.normalize('NFKC', str(text))


def extract_segment_tokens(text):
    t=normalize_text(text)
    tl=t.lower()
    canon=set()
    for phrase, canon_tok in phrase_items:
        if phrase in tl:
            canon.add(canon_tok)
    comp=set()
    words=word_re.findall(t)
    for w in words:
        wl=w.lower()
        if wl in stop_tokens:
            continue
        if wl in phrase_map:
            canon.add(phrase_map[wl])
        # identify component/net tokens
        if re.search(r'\d', w) or '_' in w or w.isupper():
            comp.add(wl)
    return canon, comp


def extract_entry_tokens(entry_text):
    t=normalize_text(entry_text)
    tl=t.lower()
    canon=set()
    for phrase, canon_tok in phrase_items:
        if phrase in tl:
            canon.add(canon_tok)
    comp=set()
    for w in word_re.findall(t):
        wl=w.lower()
        if wl in phrase_map:
            canon.add(phrase_map[wl])
        # component/net
        if re.search(r'\d', w) or '_' in w or w.isupper():
            comp.add(wl)
    return canon, comp

# build codebook entry tokens
cb_entries=defaultdict(list)
for p, cb in codebooks.items():
    for _, row in cb.iterrows():
        canon=set(); comp=set()
        if isinstance(row['keywords_examples'], str):
            c1, comp1 = extract_entry_tokens(row['keywords_examples'])
            canon |= c1; comp |= comp1
        c2, comp2 = extract_entry_tokens(row['standard_label'])
        canon |= c2; comp |= comp2
        # keep only canonical tokens for category matching
        canon = {c for c in canon if c in canonical_set}
        entry={
            'code': row['code'],
            'label': row['standard_label'],
            'canon': canon,
            'comp': comp,
            'scope': set(str(row['station_scope']).split(';')) if isinstance(row['station_scope'], str) else set(),
            'category': row['category_lv1']
        }
        cb_entries[p].append(entry)


def score_entry(seg_canon, seg_comp, entry, station):
    # weights
    comp_weight=2.0
    canon_weight=1.5
    comp_match=len(seg_comp & entry['comp'])
    canon_match=len(seg_canon & entry['canon'])
    total=comp_weight*len(entry['comp']) + canon_weight*len(entry['canon'])
    if total==0:
        return 0.0
    score=(comp_weight*comp_match + canon_weight*canon_match)/total
    # if entry expects comp tokens and none matched, penalize
    if len(entry['comp'])>0 and comp_match==0:
        score*=0.6
    if station and station in entry['scope']:
        score*=1.05
    return score

# segmentation
split_pat=re.compile(r'\s*(?:;|；|\+|&|\||\n|\t|\r|\s/\s|\sAND\s|\sand\s)\s*')

def split_segments(text):
    if text is None or (isinstance(text,float) and pd.isna(text)):
        return []
    t=str(text)
    parts=[p.strip() for p in split_pat.split(t) if p and p.strip()]
    return parts if parts else ([] if not t.strip() else [t.strip()])


def best_match(product_id, station, segment_text):
    seg_canon, seg_comp = extract_segment_tokens(segment_text)
    # ignore meta-only segments
    if (not seg_canon) and (not seg_comp):
        return None, 0.0, seg_canon, seg_comp
    best=None; best_score=0.0
    for entry in cb_entries[product_id]:
        s=score_entry(seg_canon, seg_comp, entry, station)
        if s>best_score:
            best_score=s; best=entry
    return best, best_score, seg_canon, seg_comp

# test samples
sample=logs['raw_reason_text'].dropna().sample(10, random_state=3).tolist()
for s in sample:
    product=logs.loc[logs['raw_reason_text']==s,'product_id'].iloc[0]
    station=logs.loc[logs['raw_reason_text']==s,'station'].iloc[0]
    segs=split_segments(s)
    print('RAW',s)
    for seg in segs:
        entry, score, sc, sp=best_match(product, station, seg)
        print('  seg',seg,'=>',entry['code'] if entry else None, entry['label'] if entry else None, 'score',round(score,3),'canon',sc,'comp',list(sp)[:3])
    print()

# compute distribution
scores=[]
for _, row in logs.head(1000).iterrows():
    for seg in split_segments(row['raw_reason_text']):
        entry, score, _, _=best_match(row['product_id'], row['station'], seg)
        scores.append(score)

scores_sorted=sorted(scores)
print('segments',len(scores),'avg',sum(scores)/len(scores),'p50',scores_sorted[len(scores)//2],'p75',scores_sorted[int(len(scores)*0.75)])
