        'raw_reason_text': '' if pd.isna(raw_text) else str(raw_text),
        'normalized': []
    }
    segments=split_segments(raw_text)
    seg_idx=1
    for seg in segments:
        entry, score, seg_canon, seg_comp = best_match(rec['product_id'], rec['station'], seg)
        if entry is None or score < threshold:
            pred_code='UNKNOWN'
            pred_label=''
            conf=round(min(0.49, 0.1 + 0.4*score),3)
        else:
            pred_code=entry['code']
            pred_label=entry['label']
            conf=round(score,3)
        rationale=format_rationale(entry, score, seg_canon, seg_comp, rec['station'], threshold)
        rec['normalized'].append({
            'segment_id': f"{rec['record_id']}-S{seg_idx}",
            'span_text': seg,
            'pred_code': pred_code,
            'pred_label': pred_label,
            'confidence': conf,
            'rationale': rationale
        })
        seg_idx+=1
    records.append(rec)

out={'records': records}

os.makedirs('/app/output', exist_ok=True)
with open('/app/output/solution.json','w',encoding='utf-8') as f:
    json.dump(out,f,ensure_ascii=False,indent=2)

